const MKEYS=Object.keys(MTPL).filter(k=>k!=='ministers');
const MANUAL_ORDER=['children','youth','men','women','usher','nursery','communications','dance','pastoral','admin','couples','deacon','cined','outreach','safety'];
/* one volunteer training packet per ministry: same data as the manual, different layout */
