/* ================= Course ids match course codes (LDR 103 is ldr-103). Old ids still resolve for saved progress. ================= */
const ID_MAP={};
(function(){
  const seen={};
  COURSES.forEach(c=>{
    const n=String(c.code).toLowerCase().replace(/\s+/g,'-');
    if(seen[n])throw new Error('Duplicate course code '+c.code);
    seen[n]=1;if(c.id!==n)ID_MAP[c.id]=n;
  });
  COURSES.forEach(c=>{
    ['quiz','pool','bank'].forEach(f=>{(c[f]||[]).forEach(q=>{if(q.c&&ID_MAP[q.c])q.c=ID_MAP[q.c];});});
  });
  COURSES.forEach(c=>{if(ID_MAP[c.id])c.id=ID_MAP[c.id];});
})();
/* ids removed in the restructure move to the course that absorbed them */
const ID_MERGED={'min-emerge2':'min-emerge1','min-mentor-ii':'min-mentor-i','min-mentor2':'min-mentor1','adm-410':'adm-staffvol'};
const idNew=o=>{const m=ID_MERGED[o]&&ID_MAP[ID_MERGED[o]]||ID_MAP[o];return m||ID_MAP[ID_MERGED[o]]||null;};
function idMigrate(S){
  if(!S||S.idv>=2)return S;
  try{
    const fix=k=>{
      const m=/^(u:|skip_)?([a-z]+-[a-z0-9-]+?)(\.\d+)?$/.exec(String(k));
      if(!m)return k;
      const n=ID_MAP[m[2]];
      return n?(m[1]||'')+n+(m[3]||''):k;
    };
    ['enr','comp','quiz','proj','skips','grades','lastQ','access','denied','les','ref','lesAt','bm','lnotes'].forEach(f=>{
      const o=S&&S[f];if(!o||typeof o!=='object'||Array.isArray(o))return;
      const ent=Object.keys(o).map(k=>[fix(k),o[k]]);Object.keys(o).forEach(k=>delete o[k]);ent.forEach(e=>{if(!(e[0] in o))o[e[0]]=e[1];});
    });
    if(S&&S.lastQ)Object.keys(S.lastQ).forEach(k=>{const x=S.lastQ[k];if(x&&x.miss)Object.keys(x.miss).forEach(m=>{if(ID_MAP[m]){x.miss[ID_MAP[m]]=x.miss[m];delete x.miss[m];}});});
  }catch(e){}
  S.idv=2;
  return S;
}

